import { mkdir, mkdtemp, readdir, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, relative } from "node:path";
import { $ } from "bun";

export const GENERATED_HEADER = "// @generated by tools/codegen — do not edit by hand.";

/** A set of generated files, keyed by path relative to the output directory. */
export type FileTree = Map<string, string>;

export interface SyncResult {
  written: number;
  removed: number;
  unchanged: number;
}

/**
 * Make `outDir` contain exactly `tree`. Rust files are formatted with one rustfmt run in
 * a scratch directory first, so only files whose formatted content changed are touched
 * (stable mtimes keep incremental builds fast). Anything else in `outDir` is removed —
 * the directory must be fully generated.
 */
export async function syncTree(outDir: string, tree: FileTree): Promise<SyncResult> {
  const scratch = await mkdtemp(join(tmpdir(), "simula-codegen-"));
  try {
    for (const [path, content] of tree) {
      await Bun.write(join(scratch, path), content);
    }
    const rustFiles = [...tree.keys()]
      .filter((p) => p.endsWith(".rs"))
      .map((p) => join(scratch, p));
    if (rustFiles.length > 0) await rustfmt(rustFiles);

    const result: SyncResult = { written: 0, removed: 0, unchanged: 0 };
    for (const path of tree.keys()) {
      const formatted = await Bun.file(join(scratch, path)).text();
      const target = Bun.file(join(outDir, path));
      if ((await target.exists()) && (await target.text()) === formatted) {
        result.unchanged++;
        continue;
      }
      await mkdir(dirname(join(outDir, path)), { recursive: true });
      await Bun.write(target, formatted);
      result.written++;
    }
    for (const existing of await listFiles(outDir)) {
      if (!tree.has(existing)) {
        await rm(join(outDir, existing));
        result.removed++;
      }
    }
    return result;
  } finally {
    await rm(scratch, { recursive: true, force: true });
  }
}

async function rustfmt(files: string[]) {
  const binary = Bun.which("rustfmt") ?? join(process.env.HOME ?? "", ".cargo", "bin", "rustfmt");
  // Chunk to stay under argv limits.
  for (let i = 0; i < files.length; i += 500) {
    await $`${binary} --edition 2024 ${files.slice(i, i + 500)}`.quiet();
  }
}

async function listFiles(dir: string): Promise<string[]> {
  try {
    const entries = await readdir(dir, { recursive: true, withFileTypes: true });
    return entries.filter((e) => e.isFile()).map((e) => relative(dir, join(e.parentPath, e.name)));
  } catch {
    return [];
  }
}

/**
 * Like `syncTree`, for directories that mix handwritten and generated files: writes the
 * tree, and removes only files carrying the `@generated` header that it no longer produces.
 * Files are formatted one by one via stdin (rustfmt would otherwise follow `mod` items).
 */
export async function syncGenerated(outDir: string, tree: FileTree): Promise<SyncResult> {
  const result: SyncResult = { written: 0, removed: 0, unchanged: 0 };
  for (const [path, content] of tree) {
    const formatted = path.endsWith(".rs") ? await rustfmtStdin(content) : content;
    const target = Bun.file(join(outDir, path));
    if ((await target.exists()) && (await target.text()) === formatted) {
      result.unchanged++;
      continue;
    }
    await mkdir(dirname(join(outDir, path)), { recursive: true });
    await Bun.write(target, formatted);
    result.written++;
  }
  for (const existing of await listFiles(outDir)) {
    if (tree.has(existing) || !existing.endsWith(".rs")) continue;
    const head = (await Bun.file(join(outDir, existing)).text()).split("\n", 1)[0];
    if (head === GENERATED_HEADER) {
      await rm(join(outDir, existing));
      result.removed++;
    }
  }
  return result;
}

async function rustfmtStdin(source: string): Promise<string> {
  const binary = Bun.which("rustfmt") ?? join(process.env.HOME ?? "", ".cargo", "bin", "rustfmt");
  const proc = Bun.spawn([binary, "--edition", "2024", "--emit", "stdout"], {
    stdin: "pipe",
    stdout: "pipe",
    stderr: "pipe",
  });
  proc.stdin.write(source);
  await proc.stdin.end();
  const [out, err, code] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
    proc.exited,
  ]);
  if (code !== 0) throw new Error(`rustfmt failed: ${err}`);
  return out;
}
